// Router: nhan Message Envelope (spec ARCHITECTURE.md muc 3) tu Gateway.
// Ban REVAMP (05/09/2026): bo han view_file (OneDrive) va /sync - tam thoi tat, se lam sau.
// Chi con: help / task / chitiet / taotask (placeholder) / free_text.
const items = $input.all();

function parseCommand(rawText) {
  let command = '';
  let params = '';
  if ((rawText || '').startsWith('/')) {
    const parts = rawText.trim().split(/\s+/);
    command = parts[0].toLowerCase();
    params = parts.slice(1).join(' ');
  } else {
    params = rawText || '';
  }
  return { command, params };
}

function computeRoute(command, params) {
  if (params.startsWith('chitiet_')) {
    return { route: 'chitiet', params: 'chitiet', taskId: params.replace('chitiet_', '').trim() };
  }
  if (command === '/task') return { route: 'task', params, taskId: null };
  if (command === '/help' || command === '/start') return { route: 'help', params, taskId: null };
  if (command === '/taotask') return { route: 'taotask', params, taskId: null };
  if (!command && params) return { route: 'free_text', params, taskId: null };
  return { route: 'unknown_command', params, taskId: null };
}

return items.map(it => {
  const env = it.json ?? {};
  const isCallback = env.kind === 'callback';
  const rawText = isCallback ? (env.callback?.data || '') : (env.text || '');

  let route, command = '', params = '', taskId = null;

  if (isCallback) {
    if (rawText.startsWith('chitiet_')) {
      route = 'chitiet'; taskId = rawText.replace('chitiet_', '').trim(); params = 'chitiet';
    } else {
      route = 'unknown_command'; params = rawText;
    }
  } else {
    const parsed = parseCommand(rawText);
    command = parsed.command;
    const r = computeRoute(parsed.command, parsed.params);
    route = r.route; params = r.params; taskId = r.taskId;
  }

  const legacyMessage = !isCallback ? {
    text: env.text || '',
    chat: { id: env.chat_id },
    message_id: env.raw?.message_id ?? null,
    from: { id: env.user_id, username: env.username }
  } : undefined;
  const legacyCallback = isCallback ? {
    id: env.callback?.id,
    data: env.callback?.data,
    message: { chat: { id: env.chat_id }, message_id: env.callback?.message_id }
  } : undefined;

  return {
    json: {
      route, command, params, taskId,
      chatId: env.chat_id,
      messageId: isCallback ? (env.callback?.message_id ?? null) : (env.raw?.message_id ?? null),
      isCallback,
      originalData: { ...env, message: legacyMessage, callback_query: legacyCallback }
    }
  };
});

const input = $json;
const helpText = `<b>\U0001F4D8 Danh sach lenh Telegram</b>\n\n` +
  `\U0001F449 <code>/task &lt;tu khoa&gt;</code> - Tim task\n` +
  `\U0001F449 <code>/task chitiet_&lt;id&gt;</code> - Chi tiet task\n\n` +
  `\U0001F6A7 <code>/taotask</code> - Dang xay dung lai (AI), chua kha dung.\n\n` +
  `\U0001F4CC <i>Vi du:</i>\n<code>/task linh nhi</code>`;
return [{ json: { ...input, text: helpText, parse_mode: "HTML" } }];

const raw = ($json.params || '').trim();
const normalize = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();
return [{ json: { ...$json, originalText: raw, originalText_khong_dau: normalize(raw) } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const searchText = $('Prepare Search').first().json.originalText || '';
const all = $input.all().map(i => i.json).filter(t => t && t.id); // loc bo item rong (alwaysOutputData placeholder)

const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();
const botUsername = 'Elite_clickup_bot';

if (all.length === 0) {
  return [{ json: { chatId,
    text: `❌ Không tìm thấy kết quả nào phù hợp với từ khóa <b>${escapeHtml(searchText)}</b>`,
    parse_mode: "HTML" } }];
}

const formatTask = (task, index) => {
  const link = `https://t.me/${botUsername}?start=chitiet_${task.id}`;
  const onedrive = task.onedrive_link ? cleanLink(task.onedrive_link) : '';
  const clickupUrl = task.url ? cleanLink(task.url) : '';
  return (
`<b>${index + 1}.</b> <a href="${link}">${escapeHtml(task.name)}</a>
├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}
├ List: ${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}
${onedrive ? `├ 📁 <a href="${onedrive}">Xem OneDrive</a>\n` : ''}└ 🔗 <a href="${clickupUrl}">Xem trong ClickUp</a>`
  );
};

const lines = [`🔍 <b>Kết quả tìm kiếm: ${escapeHtml(searchText)}</b>\nTìm thấy ${all.length} kết quả:`];
all.forEach((task, i) => lines.push(formatTask(task, i)));

return [{ json: { chatId, text: lines.join('\n\n'), parse_mode: "HTML" } }];

const chatId = $('Phân tích lệnh').first().json.chatId;
const all = $input.all().map(i => i.json).filter(t => t && t.id);
const escapeHtml = (t) => (t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cleanLink = (l) => (l || '').replace(/^'+|'+$/g, '').replace(/[{}]/g, '').trim();

if (all.length === 0) {
  return [{ json: { chatId, text: '❌ Không tìm thấy task này.', parse_mode: 'HTML' } }];
}
const task = all[0];
const lines = [];
lines.push(`<b>${escapeHtml(task.name)}</b>`);
lines.push(`├ Mô tả: ${escapeHtml(task.description?.trim()) || 'Không rõ'}`);
lines.push(`├ Trạng thái: ${escapeHtml(task.status) || 'Không rõ'}`);
lines.push(`├ List: ${task.list_name ? escapeHtml(task.list_name) : 'Không rõ'}`);
if (task.phu_trach) lines.push(`├ Phụ trách: ${escapeHtml(task.phu_trach)}`);
if (task.onedrive_link) {
  // Chi hien link phang - tinh nang "Xem file" (Graph API, liet ke tung file) TAM TAT theo yeu cau,
  // se lam lai o phien ban sau.
  lines.push(`├ 📁 <a href="${cleanLink(task.onedrive_link)}">Xem OneDrive</a>`);
}
lines.push(`└ 🔗 <a href="${cleanLink(task.url)}">Xem trong ClickUp</a>`);

return [{ json: { chatId, text: lines.join('\n'), parse_mode: 'HTML' } }];
